* EMOR1 -- Order entry screen 1: client ID and order type
MAP EMOR1 SIZE 24x80
  FIELD HEADER1   AT 0,2   LEN 60 PROT BRIGHT COLOR=WHITE
  FIELD CLIENTID  AT 4,20  LEN 8  UNPROT BRIGHT COLOR=WHITE
  FIELD ORDTYPE   AT 5,20  LEN 2  UNPROT BRIGHT COLOR=TURQUOISE
  FIELD MSG1      AT 10,5  LEN 60 PROT DIM    COLOR=YELLOW
  FIELD FOOTER1   AT 23,2  LEN 60 PROT DIM    COLOR=BLUE
ENDMAP
